const T = ['Demand - Client Request', 'Supply - For Rent', 'Supply - For Sale', 'Match', 'RFQ'];
const S = ['New', 'Need Verification', 'Matching', 'Matched', 'Approved for RFQ', 'RFQ Draft', 'RFQ Sent', 'Waiting Quote', 'Quote Received', 'Proposal Sent', 'Closed Won', 'Closed Lost', 'Archived', 'Available'];
const C = ['Riyadh', 'Jeddah', 'Dammam', 'Khobar', 'Makkah', 'Madinah', 'Other'];
const j = $input.first().json || {};
const t = String(j.record_type || '').trim();
const s = String(j.status || '').trim();
const c = String(j.city || '').trim();
const f = [];
if (T.includes(t)) f.push({ property: 'Record Type', select: { equals: t } });
if (S.includes(s)) f.push({ property: 'Status', select: { equals: s } });
if (C.includes(c)) f.push({ property: 'City', select: { equals: c } });
const filter = f.length ? { and: f } : { property: 'Name', title: { is_not_empty: true } };
return [{ json: { filter: JSON.stringify(filter), applied: { record_type: T.includes(t) ? t : 'all', status: S.includes(s) ? s : 'all', city: C.includes(c) ? c : 'all' } } }];
